<div class="entity-split"><section class="panel"><header class="panel-head"><div><span class="eyebrow">Integration registry</span><h2>Connections and entity bindings</h2></div><span class="panel-meta"><?= count($connections) ?> connection(s)</span></header><div class="record-list"><?php foreach($connections as$c): ?><article class="record-card"><header><div><strong><?= h($c['connection_name']) ?></strong><small><?= h(status_label($c['system_type'])) ?> · <?= h($c['provider']) ?> · <?= h($c['environment']) ?></small></div><?= badge($c['status']) ?></header><p><?= h($c['evidence_note']) ?></p><small><?= h($c['secret_reference']) ?> · adapter <?= h($c['adapter_version']) ?></small></article><?php endforeach; ?></div><h3>Entity bindings</h3><div class="table-wrap"><table><thead><tr><th>Connection</th><th>Entity</th><th>External company</th><th>Direction</th><th>Authority</th><th>Status</th></tr></thead><tbody><?php foreach($bindings as$b): ?><tr><td><?= h(entity_system_find($connections,(int)$b['connection_id'])['connection_name']??'Unknown') ?></td><td><?= h(entity_system_find($entities,(int)$b['entity_id'])['entity_name']??'Unknown') ?></td><td><?= h($b['external_company_id']?:'Unconfigured') ?></td><td><?= h(status_label($b['sync_direction'])) ?></td><td><?= h(status_label($b['data_authority'])) ?></td><td><?= badge($b['status']) ?></td></tr><?php endforeach; ?></tbody></table></div></section><section class="panel"><header class="panel-head"><div><span class="eyebrow">Secure metadata</span><h2>Create connection</h2></div></header><?php if(can('companies.administer')): ?><form class="compact-form" action="<?= h(app_url('entity-system-action.php')) ?>" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="save_connection"><input type="hidden" name="return_tab" value="integrations"><label><span>Name</span><input name="connection_name" required></label><label><span>Provider</span><input name="provider" placeholder="NetSuite, QuickBooks, SAP"></label><label><span>System type</span><select name="system_type"><option value="erp">ERP</option><option value="accounting">Accounting</option><option value="warehouse">Warehouse</option><option value="payment_provider">Payment provider</option><option value="crm">CRM</option><option value="custom_api">Custom API</option></select></label><label><span>Environment</span><select name="environment"><option value="production">Production</option><option value="sandbox">Sandbox</option><option value="testing">Testing</option></select></label><label class="span-2"><span>External secret reference</span><input name="secret_reference" value="vault://integrations/" required></label><label><span>Adapter version</span><input name="adapter_version" value="1.0"></label><label><span>Reviewer</span><select name="reviewer_id"><?php foreach(data_collection('users')as$u)if($u['status']==='active'): ?><option value="<?= (int)$u['id'] ?>"><?= h($u['name']) ?></option><?php endif; ?></select></label><label class="span-2"><span>Capabilities, comma separated</span><input name="capabilities" value="companies,suppliers,items,purchase_orders,invoices"></label><label class="span-2"><span>Evidence</span><textarea name="evidence_note" required>No credentials are stored. Activation requires adapter validation and independent review.</textarea></label><div class="span-2"><button class="button primary">Create Connection Metadata</button></div></form><hr><h3>Bind connection to entity</h3><form class="compact-form" action="<?= h(app_url('entity-system-action.php')) ?>" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="save_integration_binding"><input type="hidden" name="return_tab" value="integrations"><label><span>Connection</span><select name="connection_id"><?php foreach($connections as$c): ?><option value="<?= (int)$c['id'] ?>"><?= h($c['connection_name']) ?></option><?php endforeach; ?></select></label><label><span>Entity</span><select name="entity_id"><?php foreach($entities as$e): ?><option value="<?= (int)$e['id'] ?>"><?= h($e['entity_name']) ?></option><?php endforeach; ?></select></label><label><span>External organization</span><input name="external_organization_id"></label><label><span>External company</span><input name="external_company_id"></label><label><span>External tenant</span><input name="external_tenant_id"></label><label><span>Direction</span><select name="sync_direction"><option value="inbound">Inbound</option><option value="outbound">Outbound</option><option value="bidirectional">Bidirectional</option></select></label><label><span>Data authority</span><select name="data_authority"><option value="internal_governed">Internal governed</option><option value="external_governed">External governed</option><option value="bidirectional">Bidirectional</option></select></label><label><span>Effective</span><input type="date" name="effective_from" value="<?= date('Y-m-d') ?>"></label><label class="span-2"><span>Domains</span><input name="enabled_domains" value="companies,suppliers,items"></label><label class="span-2"><span>Evidence</span><textarea name="evidence_note" required></textarea></label><div class="span-2"><button class="button secondary">Create Draft Binding</button></div></form><?php endif; ?></section></div>
